const rows = Array.isArray($json.list) ? $json.list : [];
return rows
  .filter((row) => row && row.Id && String(row.company_name || '').trim())
  .map((row, index) => ({ json: { Id: row.Id, company_name: String(row.company_name).trim() }, pairedItem: { item: index } }));

const companyName = String($json.company_name || '').trim();
const query = companyName.replace(/"/g, '') + ' Singapore';
const baseUrl = String($env.OPENSERP_BASE_URL || 'https://searxng-railway-production-518a.up.railway.app').trim().replace(/\/+$/, '');
return {
  json: {
    ...$json,
    openserp_query: query,
    openserp_url: baseUrl + '/google/search?text=' + encodeURIComponent(query) + '&limit=10'
  }
};

const rows = $('Build OpenSERP Query').all().map((item) => item.json || {});
const searchItems = $('Search OpenSERP').all();
const groupedResults = new Map();
const groupedErrors = new Map();
function sourceIndex(item, fallback) {
  const paired = item.pairedItem;
  if (Array.isArray(paired) && Number.isInteger(paired[0]?.item)) return paired[0].item;
  if (paired && Number.isInteger(paired.item)) return paired.item;
  return fallback;
}
function extractResults(payload) {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.body)) return payload.body;
  if (Array.isArray(payload?.results)) return payload.results;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.items)) return payload.items;
  if (payload?.title || payload?.url || payload?.link) return [payload];
  return [];
}
function stringifyErrorPart(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number') return String(value);
  if (typeof value === 'object') {
    return String(value.message || value.error || value.code || value.statusCode || JSON.stringify(value));
  }
  return String(value);
}
function extractError(payload) {
  const body = payload?.body && !Array.isArray(payload.body) ? payload.body : {};
  const code = stringifyErrorPart(payload?.code || body.code || payload?.statusCode || body.statusCode);
  const message = stringifyErrorPart(payload?.message || body.message || payload?.error || body.error);
  if (!code && !message) return '';
  return [code, message].filter(Boolean).join(': ');
}
searchItems.forEach((item, fallbackIndex) => {
  const index = sourceIndex(item, fallbackIndex);
  const payload = item.json ?? {};
  const existing = groupedResults.get(index) || [];
  existing.push(...extractResults(payload));
  groupedResults.set(index, existing);
  const error = extractError(payload);
  if (error) groupedErrors.set(index, error);
});
return rows.map((row, index) => {
  const rawResults = groupedResults.get(index) || [];
  const topResults = rawResults.slice(0, 10).map((result, resultIndex) => ({
    rank: Number(result.rank || resultIndex + 1),
    title: String(result.title || '').trim(),
    url: String(result.url || result.link || '').trim(),
    snippet: String(result.content || result.snippet || result.description || '').trim()
  }));
  const openserpError = groupedErrors.get(index) || '';
  const prompt = [
    'Pick the best official website URL from the Google search results.',
    'Company: ' + row.company_name,
    'Rules:',
    '- Prefer the official company or clinic homepage.',
    '- Reject directories, reviews, social media, maps, job boards, articles, PDFs, and unrelated pages.',
    '- If none is clearly official, return an empty url.',
    '- Return JSON only: {"url":"","reason":""}',
    'Search results:',
    JSON.stringify(topResults, null, 2)
  ].join('\n');
  return {
    json: {
      Id: row.Id,
      company_name: row.company_name,
      openserp_query: row.openserp_query,
      openserp_results: topResults,
      openserp_error: openserpError,
      body: {
        model: 'deepseek/deepseek-v4-flash',
        temperature: 0,
        messages: [
          { role: 'system', content: 'You select official company homepage URLs from Google search results. Return strict JSON only.' },
          { role: 'user', content: prompt }
        ]
      }
    }
  };
});

function stripFences(value) {
  const fence = String.fromCharCode(96).repeat(3);
  return String(value || '').replace(fence + 'json', '').replaceAll(fence, '').trim();
}
function normalizeUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withProtocol = /^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = withProtocol.match(/^(https?:\/\/[^\s?#]+)(?:[?#].*)?$/i);
  return match ? match[1].replace(/\/+$/, '/') : '';
}
function canonicalDomain(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const match = raw.match(/^(?:[a-z][a-z0-9+.-]*:\/\/)?([^\s\/?#]+)/i);
  if (!match) return '';
  let hostname = match[1].split('@').pop().split(':')[0];
  hostname = hostname.toLowerCase().replace(/^www\./, '');
  const parts = hostname.split('.').filter(Boolean);
  if (parts.length <= 2) return hostname;
  const suffix2 = parts.slice(-2).join('.');
  const sgSecondLevel = new Set(['com.sg', 'org.sg', 'net.sg', 'edu.sg', 'gov.sg', 'per.sg']);
  if (sgSecondLevel.has(suffix2) && parts.length >= 3) return parts.slice(-3).join('.');
  return parts.slice(-2).join('.');
}
const prepared = $('Prepare OpenSERP Pick').all()[$itemIndex]?.json || {};
const response = $json || {};
const content = String(response.choices?.[0]?.message?.content || response.body?.choices?.[0]?.message?.content || '').trim();
let parsed = {};
try { parsed = JSON.parse(stripFences(content)); } catch {}
const searchFailed = Boolean(prepared.openserp_error) && (!Array.isArray(prepared.openserp_results) || prepared.openserp_results.length === 0);
const pickedUrl = searchFailed ? '' : normalizeUrl(parsed.url || '');
const canonical = canonicalDomain(pickedUrl);
const reason = searchFailed ? 'OpenSERP search failed before candidate selection.' : String(parsed.reason || '').trim();
const evidence = {
  query: prepared.openserp_query,
  picked_url: pickedUrl,
  canonical_domain: canonical,
  search_error: prepared.openserp_error || '',
  reason,
  first_10_results: prepared.openserp_results || [],
  llm_raw: content
};
return {
  json: {
    Id: prepared.Id,
    company_name: prepared.company_name,
    url_picked: pickedUrl,
    canonical_domain: canonical,
    duplicate_of_id: null,
    search_evidence_json: JSON.stringify(evidence),
    status: searchFailed ? 'search error' : (pickedUrl ? 'url picked' : 'no url picked'),
    last_stage: searchFailed ? 'search' : 'url_pick',
    last_error: searchFailed ? ('OpenSERP search failed: ' + prepared.openserp_error) : (pickedUrl ? '' : 'No official URL selected from first 10 OpenSERP Google results')
  }
};

const picked = $('Parse URL Pick').all()[$itemIndex]?.json || {};
const lookup = $json || {};
const dbMatches = Array.isArray(lookup.list) ? lookup.list : [];
const parsedItems = $('Parse URL Pick').all().map((item) => item.json || {});
const earlierBatchDuplicate = parsedItems
  .filter((item) => item.canonical_domain && item.canonical_domain === picked.canonical_domain)
  .filter((item) => Number(item.Id) < Number(picked.Id))
  .sort((a, b) => Number(a.Id) - Number(b.Id))[0];
const dbDuplicate = dbMatches
  .filter((row) => Number(row.Id) !== Number(picked.Id))
  .sort((a, b) => Number(a.Id) - Number(b.Id))[0];
const duplicate = dbDuplicate || earlierBatchDuplicate || null;
if (picked.canonical_domain && duplicate) {
  return {
    json: {
      ...picked,
      duplicate_of_id: Number(duplicate.Id),
      status: 'url duplicate',
      last_stage: 'dedupe',
      last_error: 'Duplicate canonical_domain ' + picked.canonical_domain + ' of row ' + duplicate.Id
    }
  };
}
return { json: picked };
